const leads = $input.all().map(i => i.json);

// Data de 7 dias atrás
const agora = new Date();
const seteDiasAtras = new Date();
seteDiasAtras.setDate(agora.getDate() - 7);

// Filtrar apenas leads da última semana
const leadsSemana = leads.filter(l => {
  if (!l['Data/Hora']) return false;
  // Tenta parsear a data no formato pt-BR: DD/MM/YYYY HH:mm
  const partes = l['Data/Hora'].split(' ');
  const dataParts = (partes[0] || '').split('/');
  if (dataParts.length < 3) return false;
  const dataLead = new Date(dataParts[2], dataParts[1]-1, dataParts[0]);
  return dataLead >= seteDiasAtras;
});

const total        = leadsSemana.length;
const qualificados = leadsSemana.filter(l => l.Status && l.Status !== 'Novo').length;
const transferidos = leadsSemana.filter(l => l.Status === 'Transferido').length;
const fechados     = leadsSemana.filter(l => l.Status === 'Fechado').length;
const perdidos     = leadsSemana.filter(l => l.Status === 'Perdido').length;

const taxaConversao = total > 0 ? ((fechados / total) * 100).toFixed(1) : 0;
const taxaQualif    = total > 0 ? ((qualificados / total) * 100).toFixed(1) : 0;

// Contar leads por dia da semana
const diasSemana = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
const porDia = {};
diasSemana.forEach(d => porDia[d] = 0);

leadsSemana.forEach(l => {
  if (!l['Data/Hora']) return;
  const partes = l['Data/Hora'].split(' ');
  const dataParts = (partes[0] || '').split('/');
  if (dataParts.length < 3) return;
  const dataLead = new Date(dataParts[2], dataParts[1]-1, dataParts[0]);
  const dia = diasSemana[dataLead.getDay()];
  porDia[dia] = (porDia[dia] || 0) + 1;
});

const diaTop = Object.entries(porDia).sort((a,b) => b[1]-a[1])[0];

const dataInicio = seteDiasAtras.toLocaleDateString('pt-BR');
const dataFim    = agora.toLocaleDateString('pt-BR');

return [{
  json: {
    total, qualificados, transferidos, fechados, perdidos,
    taxaConversao, taxaQualif,
    porDia,
    diaTop: diaTop ? `${diaTop[0]} (${diaTop[1]} leads)` : 'N/A',
    periodo: `${dataInicio} a ${dataFim}`
  }
}];

const m = $input.first().json;

const barras = Object.entries(m.porDia)
  .map(([dia, qtd]) => `${dia}: ${'█'.repeat(qtd)}${'░'.repeat(Math.max(0, 5-qtd))} (${qtd})`)
  .join('\n');

const mensagem = `📊 *Relatório Semanal — AutoAtende*
` +
  `Período: ${m.periodo}\n\n` +
  `📥 Leads recebidos: *${m.total}*\n` +
  `✅ Qualificados: *${m.qualificados}* (${m.taxaQualif}%)\n` +
  `💬 Transferidos para humano: *${m.transferidos}*\n` +
  `🤝 Fechados: *${m.fechados}*\n` +
  `🎯 Taxa de conversão: *${m.taxaConversao}%*\n\n` +
  `📅 Leads por dia:\n${barras}\n\n` +
  `📈 Dia mais movimentado: ${m.diaTop}\n\n` +
  `_Relatório gerado automaticamente pelo AutoAtende_ 🤖`;

return [{ json: { mensagem } }];
